/**
 * Private S3 report-object adapter. Server-side only.
 *
 * Credentials must be scoped to the Preview bucket and never exposed to the client.
 * Object keys are generated by the server, not accepted from user input.
 */
import "server-only";
import { createHash, createHmac, randomUUID } from "node:crypto";

const MAX_REPORT_BYTES = 25 * 1024 * 1024;
const sha256 = (value: Buffer | string) => createHash("sha256").update(value).digest("hex");
const hmac = (key: Buffer | string, value: string) => createHmac("sha256", key).update(value).digest();

function config() {
  const bucket = process.env.REPORT_STORAGE_BUCKET;
  const region = process.env.REPORT_STORAGE_REGION;
  const accessKeyId = process.env.REPORT_STORAGE_ACCESS_KEY;
  const secretAccessKey = process.env.REPORT_STORAGE_SECRET_KEY;
  if (!bucket || !region || !accessKeyId || !secretAccessKey) {
    throw new Error("REPORT_STORAGE_NOT_CONFIGURED");
  }
  if (!/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/.test(bucket) ||
      !/^[a-z]{2}(?:-gov)?-[a-z]+-\d$/.test(region)) {
    throw new Error("REPORT_STORAGE_INVALID_CONFIG");
  }
  return { bucket, region, accessKeyId, secretAccessKey };
}

function isPdf(data: Buffer) {
  return data.length >= 5 && data.subarray(0, 5).toString("ascii") === "%PDF-";
}

export function validatePatientReportPdf(data: Buffer) {
  if (!isPdf(data)) throw new Error("REPORT_INVALID_PDF");
  if (data.length > MAX_REPORT_BYTES) throw new Error("REPORT_TOO_LARGE");
  return data;
}

export function newPatientReportObjectKey(bookingId: string) {
  if (!/^[a-zA-Z0-9_-]{1,128}$/.test(bookingId)) throw new Error("INVALID_BOOKING_ID");
  return `patient-reports/${bookingId}/${randomUUID()}.pdf`;
}

function validateKey(key: string) {
  if (!/^patient-reports\/[a-zA-Z0-9_-]{1,128}\/[a-f0-9-]{36}\.pdf$/.test(key)) {
    throw new Error("INVALID_REPORT_OBJECT_KEY");
  }
}

async function signedRequest(method: "PUT" | "GET" | "DELETE", key: string, body?: Buffer) {
  validateKey(key);
  const { bucket, region, accessKeyId, secretAccessKey } = config();
  const host = `s3.${region}.amazonaws.com`;
  const path = `/${bucket}/${key}`;
  const now = new Date();
  const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, "");
  const date = amzDate.slice(0, 8);
  const payloadHash = sha256(body ?? Buffer.alloc(0));
  const headers: Record<string, string> = {
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
  };
  if (method === "PUT") {
    headers["content-type"] = "application/pdf";
    headers["x-amz-server-side-encryption"] = "AES256";
  }
  const signedHeaders = Object.keys(headers).sort().join(";");
  const canonicalHeaders = Object.entries(headers).sort(([a], [b]) => a.localeCompare(b))
    .map(([name, value]) => `${name}:${value.trim()}\n`).join("");
  const canonicalRequest = [
    method, path, "", canonicalHeaders, signedHeaders, payloadHash,
  ].join("\n");
  const scope = `${date}/${region}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256", amzDate, scope, sha256(canonicalRequest),
  ].join("\n");
  const dateKey = hmac(`AWS4${secretAccessKey}`, date);
  const regionKey = hmac(dateKey, region);
  const serviceKey = hmac(regionKey, "s3");
  const signingKey = hmac(serviceKey, "aws4_request");
  const signature = createHmac("sha256", signingKey).update(stringToSign).digest("hex");
  const authorization = `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${scope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;
  const response = await fetch(`https://${host}${path}`, {
    method,
    headers: { ...headers, authorization },
    body: body ? new Uint8Array(body) : undefined,
    cache: "no-store",
    signal: AbortSignal.timeout(30_000),
  });
  if (!response.ok) {
    // Do not leak bucket names, internal URLs or AWS error response bodies.
    throw new Error(`REPORT_STORAGE_REQUEST_FAILED_${response.status}`);
  }
  return response;
}

export async function uploadPatientReportPdf(bookingId: string, data: Buffer) {
  validatePatientReportPdf(data);
  const key = newPatientReportObjectKey(bookingId);
  await signedRequest("PUT", key, data);
  return { key, bytes: data.length, sha256: sha256(data) };
}

export async function downloadPatientReportPdf(key: string) {
  const response = await signedRequest("GET", key);
  const contentLength = Number(response.headers.get("content-length") || 0);
  if (contentLength > MAX_REPORT_BYTES) throw new Error("REPORT_TOO_LARGE");
  const data = Buffer.from(await response.arrayBuffer());
  return validatePatientReportPdf(data);
}

export async function deletePatientReportPdf(key: string) {
  await signedRequest("DELETE", key);
}
